import numpy as np,json
from pathlib import Path
from scipy.interpolate import CubicSpline,PchipInterpolator
from scipy.integrate import quad
from scipy.signal import find_peaks
from shapely.geometry import LineString,LinearRing,Polygon
D=Path(__file__).parent;j=json.loads((D/'geometrie.json').read_text());a=np.loadtxt(D/'coordonnees.csv',delimiter=',',skiprows=1);p=np.array(j['control_points_xy']);t=np.array(j['parameter_knots']);c=CubicSpline(t,p,bc_type='periodic');L=sum(quad(lambda u: np.linalg.norm(c(u,1)),t[i],t[i+1],epsabs=1e-8)[0] for i in range(len(t)-1));v=c(np.linspace(0,t[-1],100001),1);xy=c(np.linspace(0,t[-1],100001));d=c(np.linspace(0,t[-1],100001),2);s=np.r_[0,np.cumsum(np.linalg.norm(np.diff(xy,axis=0),axis=1))];curv=(v[:,0]*d[:,1]-v[:,1]*d[:,0])/np.linalg.norm(v,axis=1)**3;rad=1/np.maximum(abs(curv),1e-20);eh=np.array(j['elevation_knots_s_h']);wh=np.array(j['width_knots_s_w']);h=PchipInterpolator(eh[:,0],eh[:,1]);w=PchipInterpolator(wh[:,0],wh[:,1]);normal=np.c_[-v[:,1],v[:,0]]/np.linalg.norm(v,axis=1)[:,None];left=xy+normal*w(s)[:,None]/2;right=xy-normal*w(s)[:,None]/2;heads=np.unwrap(np.arctan2(v[:,1],v[:,0]));peaks=find_peaks(abs(curv),prominence=.0005)[0];result={'length_quad':L,'length_csv_3d':np.linalg.norm(np.diff(a[:,1:4],axis=0),axis=1).sum(),'closure_position':np.linalg.norm(c(0)-c(t[-1])),'closure_tangent':np.linalg.norm(c(0,1)-c(t[-1],1)),'closure_curvature':np.linalg.norm(c(0,2)-c(t[-1],2)),'closure_slope':float(h(0,1)-h(eh[-1,0],1)),'closure_width':float(w(0)-w(eh[-1,0])),'left_simple':LineString(left).is_simple,'right_simple':LineString(right).is_simple,'edges_intersect':LineString(left).intersects(LineString(right)),'min_radius':float(rad.min()),'grade_min':float(h(s,1).min()*100),'grade_max':float(h(s,1).max()*100),'curve_peaks':[{'s':float(s[i]),'radius':float(rad[i]),'sign':float(np.sign(curv[i]))} for i in peaks]};print(json.dumps(result,indent=2));(D/'verification-independante.json').write_text(json.dumps(result,indent=2))
